"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[929],{3929:(e,n,i)=>{i.r(n),i.d(n,{content:()=>a,description:()=>t,title:()=>s});i(5043);var r=i(579);const s="Eine kurze Geschichte von Whimsylabs: Von unserem bescheidenen Anfang zu einem BETT 2025 Gewinner",t="Wie Whimsylabs, gegr\xfcndet von Dr. Marisa French, MINT-Herausforderungen mit vollst\xe4ndig simulierten Laboren, wirkungsvollen Partnerschaften und preisgekr\xf6nter Innovation angeht.",a=(0,r.jsxs)("div",{children:[(0,r.jsx)("p",{children:"Whimsylabs wurde urspr\xfcnglich 2020 von Marisa French gegen Ende ihrer Physik-Promotion gegr\xfcndet, gerade als die COVID-19 Pandemie ihren ersten H\xf6hepunkt erreichte. Die verheerenden Auswirkungen von COVID-19, die traditionelle Lehre in Laborumgebungen lahmlegten, lie\xdfen viele Studierende jahrelang ohne Zugang zu praktischer wissenschaftlicher Bildung. Gekoppelt mit dem R\xfcckgang der MINT-Rankings des Vereinigten K\xf6nigreichs, durch den es auf den 15. Platz im Wissenschafts-Rankings des OECD Programme for International Student Assessment (PISA) fiel, bahnte sich eine Krise f\xfcr die britische Bildung an, sehr pers\xf6nlich anf\xfchlte, da Marisa damals aufgrund der Praktika, die sie in der Sekundarschule erlebte, f\xfcr die Wissenschaft begeistert wurde."}),(0,r.jsx)("p",{children:"Angetrieben von dem Wunsch, einen bedeutsamen Wandel zu schaffen, nutzte Marisa ihre Simulations- und Gaming-F\xe4higkeiten, um ein vollst\xe4ndig simuliertes, virtuelles Sandbox-Labor zu erschaffen. Die Forschung zeigt, dass simulationsbasierte Lernumgebungen das Studierendeengagement und die Lernergebnisse erheblich verbessern k\xf6nnen, besonders in MINT-Bereichen, wo praktisches Experimentieren entscheidend ist. Sie entwarf ihr Labor, um eine sichere, zug\xe4ngliche und ansprechende Umgebung f\xfcr praktisches Lernen zu entwickeln, ganz ohne die Risiken oder Kosten, die mit traditionellen Laboren verbunden sind. Das Ziel war einfach: ein virtuelles Labor zu schaffen, das vollst\xe4ndig den Spa\xdf einfing, den sie in ihren Schullaboren erlebt hatte, und das von jedem, \xfcberall, jederzeit genutzt werden kann."}),(0,r.jsx)("img",{src:"/images/oldLab.png",alt:"Erstes Mockup-Labor",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das erste Labor-Mockup: Ein einfacher Prototyp zur Konzeptualisierung der Vision f\xfcr Whimsylabs."}),(0,r.jsx)("p",{children:"Die Reise begann bescheiden mit einem rudiment\xe4ren Labor-Mockup, das dazu diente, erste Programmierideen zu testen. Von Anfang an war der Traum eines einheitlichen virtuellen Labors klar, aber der Weg zur Verwirklichung war weniger klar. Mit akademischen Simulationen als Grundlage war die erste Laborversion ein einfacher Prototyp, der das Fundament legte, um Ideen zu testen und die Vision zu verfeinern. Da jedoch die meisten akademischen Simulationen Supercomputer ben\xf6tigen und Monate zum Laufen brauchen, bestand die Herausforderung darin, die Simulationen in Echtzeit auf einer ma\xdfgeschneiderten VR-Plattform laufen zu lassen."}),(0,r.jsx)("p",{children:"Der gr\xf6\xdfte Teil der Arbeit fiel darauf ab, Berechnungen zu verfeinern, damit sie in Echtzeit laufen k\xf6nnen, w\xe4hrend sie immer noch realistische Ergebnisse produzieren. Das erste Labor war ein reiner Machbarkeitsbeweis, der zeigte, dass die Simulationen in Echtzeit laufen k\xf6nnen und dass man mit ihnen live auf bedeutsame Weise interagien kann. Studien in der computergest\xfctzten Physiklehre heben die Bedeutung von Echtzeit-Interaktion f\xfcr konzeptionelles Verst\xe4ndnis hervor, da sofortiges Feedback Studierenden hilft, theoretische Konzepte mit beobachtbaren Ph\xe4nomenen zu verbinden."}),(0,r.jsx)("p",{children:"Um diese Zeit erregte Whimsylabs die Aufmerksamkeit der Universit\xe4t Edinburgh, die von unserer bahnbrechenden Arbeit mit Simulationen und ehrgeizigen Zielen begeistert war. Dies sicherte Whimsylabs einen Platz im prestigetr\xe4chtigen Inkubatorprogramm und gewann den \u201eSummer Accelerator\u201c. Mit diesen Durchbr\xfcchen und Anerkennungen konnten wir unsere erste Finanzierungsrunde sichern, um eine ma\xdfgeschneiderte VR/Web-Kombiplattform zu erschaffen, und brachte unseren zweiten Gr\xfcnder zum Projekt, um beim Aufbau des Labors zu helfen; ein Doktor der Chemie mit jahrelanger Erfahrung im Training und der Ausbildung f\xfcr die Chemieindustrie."}),(0,r.jsx)("img",{src:"/images/testLab.png",alt:"Zweites Tech-Test-Labor",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das zweite Labor: Ein Testgel\xe4nde f\xfcr fortschrittliche Simulationstechnologien."}),(0,r.jsx)("p",{children:"Das zweite Labor wurde entwickelt, um herauszufinden, wie wir das Labor mehr wie ein echtes Labor und weniger wie ein Videospiel gestalten k\xf6nnen. Dies war das erste Mal, dass wir ber\xfccksichtigen, wie das Labor in einer echten Bildungsumgebung verwendet werden w\xfcrde, um die Bewegungen und Aktionen eines Labors zu lehren. Diese Ph\xe4nomenologie des Labors erwies sich als entscheidend f\xfcr Studierende, um ein Muskelged\xe4chtnis aufzubauen, das ben\xf6tigt wird, um Verfahren in realen Laboren durchzuf\xfcrhren, wie Fl\xfcssigkeitsphysik und realistische, physischen Interaktionen. Die Forschung in k\xf6rperbezogener Ged\xe4chtnisentwicklung zeigt, dass physische Bewegungen und Gesten das Lernen und den Abruf von Wissen in wissenschaftlichen Kontexten erheblich verbessern."}),(0,r.jsx)("p",{children:"Das zweite Labor war ein Erfolg, und wir konnten Schulen erreichen, um das Labor in einer echten Bildungsumgebung zu testen. Das Feedback war \xfcberw\xe4ltigend positiv, wobei Studierende und Lehrkr\xe4fte gleicherma\xdfen das Labor f\xfcr seinen Realismus und seine Benutzerfreundlichkeit lobten. Dies war ein kritischer Schritt in der Entwicklung, da dies zeigte, dass das Labor in einer echten Bildungsumgebung verwendet werden und ein wertvolles Werkzeug des Lehrens und Lernens sein kann. Es gab nur ein Problem: das Labor war h\xe4sslich."}),(0,r.jsx)("img",{src:"/images/finalLab.png",alt:"Finales Labordesign",className:"rounded shadow center limited-size"}),(0,r.jsx)("p",{className:"caption",children:"Das finale Labor: Eine Mischung aus modernster Technologie und einladendem Design, das hervorsticht."}),(0,r.jsx)("p",{children:"Mit diesem Gedanken machten wir uns daran, das Labor von Grund auf komplett neu zu gestalten. Aufgrund der begrenzten Leistung von VR-Headsets und der Berechnungskosten der fortschrittlichen Simulationen gab es jedoch wenig Raum, um hochaufl\xf6senden Realismus zu reflektieren. Eine weitere \xdcberlegung war die breite Altersspanne der Nutzenden, die das Labor erfahren w\xfcrde, von 5 bis \xfcber 18 Jahren, und die Notwendigkeit, das Labor f\xfcr alle zug\xe4nglich zu machen. Diese Richtungswahl war schwierig, aber am Ende wurden wir von einem unserer urspr\xfcnglichen W\xfcnsche geleitet, dass das Labor ein Ort des Staunens und der Erkundung ist und dass es ein Ort sein sollte, zu dem Studierende zur\xfcckkehren wollen. Forschung in der Bildungspsychologie betont die Bedeutung intrinsischer Motivation und neugiergetriebenem Lernen in der MINT-Bildung. Um diese Zeit entschieden wir uns f\xfcr unsere Whimsycat als Logo und Maskottchen, ein Symbol wie kein anderes im virtuellen Laborbereich, das die Neugier und das Staunen verk\xf6rpert, das wir in unseren Studierenden inspirieren wollen."}),(0,r.jsx)("p",{children:"Das finale Labordesign war eine Mischung aus modernster Technologie und einladendem Design, das im \xfcberf\xfcllten Edtech-Bereich hervorsticht. Unser Labor war nun eine vollst\xe4ndig realisierte virtuelle Umgebung, die mit einer breiten Palette von Experimenten und Simulationen \xfcber Chemie, Physik und Biologie Vielf\xe4ltigkeit bietet. Mit diesem Labor konnten wir an der prestigetr\xe4chtigen \u201eConverge Challenge\u201c teilnehmen, einem Wettbewerb f\xfcr die besten neuen Unternehmen in Schottland, und einen Platz im Finale unter der Kategorie \u201eCreate Change\u201c sichern, wo wir den zweiten Platz unter allen Unternehmen in Schottland belegten."}),(0,r.jsx)("p",{children:"Durch unseren Sieg bei Converge sicherten wir uns die Mittel, um an der \u201eBETT UK\u201c teilzunehmen und unsere Innovationen auf eine globale B\xfchne zu bringen. Das Feedback von Studierenden und P\xe4dagogen gleicherma\xdfen war \xfcberw\xe4ltigend positiv, wobei viele hervorhoben, wie die Plattform die MINT-Bildung transformiert. Zus\xe4tzlich war Whimsylabs' innovativer Ansatz nicht unbemerkt geblieben. Die Plattform wurde vom \u201eEpping Forest Schools Partnership Trust\u201c als Teil der \u201eKids Judge Bett\u201c anerkannt, wo Sch\xfcler Whimsylabs f\xfcr ihre Nutzung virtueller Labore nominierten, um Studierende in Laborumgebungen zu unterrichten, und gleichzeitig ein m\xe4chtiges Werkzeug f\xfcr Nachhaltigkeit bereitstellt. Diese Anerkennung hebt die Kraft unserer Mission hervor, die n\xe4chste Generation von MINT-F\xfchrungskr\xe4ften zu inspirieren."}),(0,r.jsx)("p",{children:"W\xe4hrend Whimsylabs in den letzten Jahren still seine Technologie entwickelt hat, fl\xfcsterleise zusammen mit einigen Pilotschulen, sind wir nun bereit, L\xe4rm zu machen und laut \xfcber unsere bahnbrechende L\xf6sung zu berichten. Mit einem starken Fundament, einem wachsenden Team und einer bew\xe4hrten Erfolgsbilanz der Innovation ist Whimsylabs bereit, die wissenschaftliche Bildung zu transformieren und die n\xe4chste Generation von MINT-F\xfchrungskr\xe4ften zu inspirieren, w\xe4hrend wir unseren Kernwerten treu bleiben: Ein Sandbox-Labor zu schaffen, dass die Physikalit\xe4t von Laboren mit dem Spa\xdf und dem Staunen der Wissenschaft zusammenbringt, und den Zugang zu exzellenter Wissenschaftsbildungstechnologie f\xfcr alle Institutionen weltweit demokratisiert."})]})}}]);
